import { useEffect, useState } from 'react';
import { routinePeriod } from '../shared/life';
import type { RoutinePeriod } from '../shared/types';
import morning from './assets/rooms/morning.webp';
import afternoon from './assets/rooms/afternoon.webp';
import evening from './assets/rooms/evening.webp';
import night from './assets/rooms/night.webp';

/** The same shared studio at four times of day (generated by Gptia), following the members' routine periods. */
const ROOMS: Record<RoutinePeriod, string> = { morning, afternoon, evening, night };
const KEY = 'airoom.room.backdrop', CHANGED = 'airoom:room-backdrop';

/** A per-machine display preference; on unless the user turned it off. */
export function roomBackdropEnabled() { try { return localStorage.getItem(KEY) !== 'off'; } catch { return true; } }
export function setRoomBackdropEnabled(on: boolean) {
  try { localStorage.setItem(KEY, on ? 'on' : 'off'); } catch { /* Still applies until the window reloads. */ }
  window.dispatchEvent(new Event(CHANGED));
}

/** The room behind the chat: all four pictures stay loaded and the current one fades in, so the hour turning is a slow change of light. */
export function RoomBackdrop({ now = () => new Date() }: { now?: () => Date }) {
  const [on, setOn] = useState(roomBackdropEnabled), [period, setPeriod] = useState(() => routinePeriod(now().getHours()));
  useEffect(() => {
    const timer = window.setInterval(() => setPeriod(routinePeriod(now().getHours())), 60_000);
    const sync = () => setOn(roomBackdropEnabled());
    window.addEventListener(CHANGED, sync);
    return () => { window.clearInterval(timer); window.removeEventListener(CHANGED, sync); };
  }, []);
  if (!on) return null;
  return <div className="room-backdrop" aria-hidden="true" data-period={period}>
    {(Object.keys(ROOMS) as RoutinePeriod[]).map(id => <div key={id} className={`room-backdrop-layer ${id === period ? 'current' : ''}`} style={{ backgroundImage: `url(${ROOMS[id]})` }} />)}
  </div>;
}
